/** The requests the adapter sends: their params and results by method. */
export interface ClientRequests {
  initialize: { params: InitializeParams; result: InitializeResponse };
  'model/list': { params: ModelListParams; result: ModelListResponse };
  'account/read': { params: GetAccountParams; result: GetAccountResponse };
  'thread/start': { params: ThreadStartParams; result: ThreadStartResponse };
  'thread/resume': { params: ThreadResumeParams; result: ThreadResumeResponse };
  'thread/fork': { params: ThreadForkParams; result: ThreadForkResponse };
  'thread/revert': { params: ThreadRevertParams; result: ThreadRevertResponse };
  'thread/list': { params: ThreadListParams; result: ThreadListResponse };
  'thread/turns/list': { params: ThreadTurnsListParams; result: ThreadTurnsListResponse };
  'thread/compact/start': { params: ThreadCompactStartParams; result: ThreadCompactStartResponse };
  'thread/backgroundTerminals/list': { params: ThreadBackgroundTerminalsListParams; result: ThreadBackgroundTerminalsListResponse };
  'thread/backgroundTerminals/terminate': {
    params: ThreadBackgroundTerminalsTerminateParams;
    result: ThreadBackgroundTerminalsTerminateResponse;
  };
  'thread/backgroundTerminals/clean': { params: ThreadBackgroundTerminalsCleanParams; result: ThreadBackgroundTerminalsCleanResponse };
  'turn/start': { params: TurnStartParams; result: TurnStartResponse };
  'turn/steer': { params: TurnSteerParams; result: TurnSteerResponse };
  'turn/interrupt': { params: TurnInterruptParams; result: TurnInterruptResponse };
}

/** The app-server's requests: their params and the answers by method. */
export interface ServerRequests {
  'item/commandExecution/requestApproval': {
    params: CommandExecutionRequestApprovalParams;
    result: CommandExecutionRequestApprovalResponse;
  };
  'item/fileChange/requestApproval': { params: FileChangeRequestApprovalParams; result: FileChangeRequestApprovalResponse };
  'item/tool/requestUserInput': { params: ToolRequestUserInputParams; result: ToolRequestUserInputResponse };
  'mcpServer/elicitation/request': { params: McpServerElicitationRequestParams; result: McpServerElicitationRequestResponse };
  'item/permissions/requestApproval': { params: PermissionsRequestApprovalParams; result: PermissionsRequestApprovalResponse };
  'item/tool/call': { params: DynamicToolCallParams; result: DynamicToolCallResponse };
  'account/chatgptAuthTokens/refresh': { params: ChatgptAuthTokensRefreshParams; result: ChatgptAuthTokensRefreshResponse };
  'attestation/generate': { params: AttestationGenerateParams; result: AttestationGenerateResponse };
  applyPatchApproval: { params: ApplyPatchApprovalParams; result: ApplyPatchApprovalResponse };
  execCommandApproval: { params: ExecCommandApprovalParams; result: ExecCommandApprovalResponse };
}

/** The app-server's notifications the adapter maps: their params by method. */
export interface ServerNotifications {
  'turn/started': TurnStartedNotification;
  'turn/completed': TurnCompletedNotification;
  'item/started': ItemStartedNotification;
  'item/completed': ItemCompletedNotification;
  'item/agentMessage/delta': AgentMessageDeltaNotification;
  'item/plan/delta': PlanDeltaNotification;
  'item/reasoning/summaryTextDelta': ReasoningSummaryTextDeltaNotification;
  'item/reasoning/summaryPartAdded': ReasoningSummaryPartAddedNotification;
  'item/commandExecution/outputDelta': CommandExecutionOutputDeltaNotification;
  'item/commandExecution/terminalInteraction': TerminalInteractionNotification;
  'process/exited': ProcessExitedNotification;
  'thread/reverted': ThreadRevertedNotification;
  'thread/tokenUsage/updated': ThreadTokenUsageUpdatedNotification;
  'account/rateLimits/updated': AccountRateLimitsUpdatedNotification;
  'thread/name/updated': ThreadNameUpdatedNotification;
  error: ErrorNotification;
  'serverRequest/resolved': ServerRequestResolvedNotification;
}

/**
 * A path that is guaranteed to be absolute and normalized (though it is not guaranteed to be canonicalized or exist on the filesystem).
 *
 * IMPORTANT: When deserializing an `AbsolutePathBuf`, a base path must be set using [AbsolutePathBufGuard::new]. If no base path is set, the deserialization will fail unless the path being deserialized is already absolute.
 */
export type AbsolutePathBuf = string;

export type Account =
  | {
      type: 'apiKey';
    }
  | {
      email: string | null;
      planType: PlanType;
      type: 'chatgpt';
      /**
       * Display name of the selected ChatGPT workspace, when available.
       */
      workspaceName?: string | null;
    }
  | {
      type: 'amazonBedrock';
      usesCodexManagedCredentials?: boolean;
    }
  | {
      type: 'gcp';
    };

/**
 * Sparse rolling rate-limit update.
 *
 * Clients should merge available values into the most recent `account/rateLimits/read` response or refetch that snapshot. Nullable account metadata may be unavailable in a rolling update and does not clear a previously observed value.
 */
export type AccountRateLimitsUpdatedNotification = {
  rateLimits: RateLimitSnapshot;
};

/**
 * Backend routing policy. Wire values match the accounts/check contract.
 */
export type AccountRoutingOverride = 'NO_CONSTRAINT' | 'us' | 'us_cr';

export type ActivePermissionProfile = {
  /**
   * Parent profile identifier from the selected permissions profile's `extends` setting, when present.
   */
  extends?: string | null;
  /**
   * Identifier from `default_permissions` or the implicit built-in default, such as `:workspace` or a user-defined `[permissions.<id>]` profile.
   */
  id: string;
};

export type AdditionalContextEntry = {
  kind: AdditionalContextKind;
  /**
   * Optional name for untrusted context, used to label its tool output.
   */
  name?: string | null;
  value: string;
};

export type AdditionalContextKind = 'untrusted' | 'application';

export type AdditionalFileSystemPermissions = {
  entries?: Array<FileSystemSandboxEntry> | null;
  globScanMaxDepth?: number | null;
  /**
   * This will be removed in favor of `entries`.
   */
  read?: Array<LegacyAppPathString> | null;
  /**
   * This will be removed in favor of `entries`.
   */
  write?: Array<LegacyAppPathString> | null;
};

export type AdditionalNetworkPermissions = {
  enabled?: boolean | null;
};

export type AdditionalPermissionProfile = {
  fileSystem?: AdditionalFileSystemPermissions | null;
  /**
   * Partial overlay used for per-command permission requests.
   */
  network?: AdditionalNetworkPermissions | null;
};

