export type UserInput =
  | {
      text: string;
      /**
       * UI-defined spans within `text` used to render or persist special elements.
       */
      text_elements?: Array<TextElement>;
      type: 'text';
    }
  | ((
      | {
          url: string;
        }
      | {
          fileId: string;
        }
    ) & {
      detail?: ImageDetail | null;
      type: 'image';
    })
  | {
      detail?: ImageDetail | null;
      path: string;
      type: 'localImage';
    }
  | ((
      | {
          url: string;
        }
      | {
          fileId: string;
        }
    ) & {
      type: 'audio';
    })
  | {
      path: string;
      type: 'localAudio';
    }
  | {
      name: string;
      path: string;
      type: 'skill';
    }
  | {
      name: string;
      path: string;
      type: 'mention';
    };

